vector<int> g[N];
int dp[N][2];
void dfs(int u,int f){
    int kid = 0;
    for(int i=0;i<g[u].size();i++){
        int v = g[u][i];
        if(v==f) continue;
        dfs(v,u);
        kid ++;

    }
    if(!kid) dp[u][1]=1, dp[u][0] = 0;
    else{
        dp[u][0] = 0;
        for(int i=0;i<g[u].size();i++){
            int v = g[u][i];
            if(v==f)continue;
            dp[u][0] += dp[v][1];
        }
        dp[u][1] = 1;
        for(int i=0;i<g[u].size();i++){
            int v = g[u][i];
            if(v==f) continue;
            dp[u][1] += min(dp[v][1],dp[v][0]);
        }
    }
}
